async def act(page):
    """
    Create a new Shopping Cart Price Rule named "Fall Discount" that gives $10 off at checkout for all customers.

    Strategy:
    - Use a relative goto to open the Add New Shopping Cart Price Rule page.
    - Use Accessibility Tree-centric selectors (page.get_by_role) for all interactions.
    - Attempt multiple plausible label variants where Magento's admin UI might differ.
    - Check all websites and all customer groups by iterating checkbox controls inside the expected groups.
    - Set Coupon to "No Coupon" (automatic) and set the action to a fixed cart discount of 10.
    - Click the Save button (this navigation is left as the last action).
    """
    import asyncio

    # There are no knowledge_base helper functions available for this task.
    # (If there were, we'd call them here; we checked and none exist.)

    # 1) Navigate to the Add New Shopping Cart Price Rule page
    await page.goto('/index.php/admin/promo_quote/new/')
    await page.wait_for_load_state('networkidle')
    await asyncio.sleep(0.5)

    # Helper to try multiple role-name variants for textbox filling
    async def try_fill_textbox(possible_names, value):
        for name in possible_names:
            try:
                await page.get_by_role('textbox', name=name).fill(value)
                return True
            except Exception:
                # not found or not interactable, try next
                pass
        return False

    # Helper to try selecting a combobox option by label then by value
    async def try_select_combobox(possible_names, option_labels=None, option_values=None):
        option_labels = option_labels or []
        option_values = option_values or []
        for name in possible_names:
            try:
                comb = page.get_by_role('combobox', name=name)
                # try labels first
                for lbl in option_labels:
                    try:
                        await comb.select_option(label=lbl)
                        return True
                    except Exception:
                        pass
                for val in option_values:
                    try:
                        await comb.select_option(value=val)
                        return True
                    except Exception:
                        pass
            except Exception:
                pass
        return False

    # 2) Fill Rule Name and Description
    await try_fill_textbox(['Rule Name', 'Name', 'Rule name', 'rule name'], 'Fall Discount')
    # Description may be a larger textbox/textarea; try common labels
    await try_fill_textbox(['Description', 'Rule Description', 'Description (for internal use)'], 'Fall discount: $10 off at checkout for all customers.')

    # 3) Set Status = Active (try combobox or radios)
    await try_select_combobox(['Status', 'Rule Status'], option_labels=['Active'], option_values=['1', 'active'])

    # 4) Ensure all Websites are selected (if a Websites group exists)
    try:
        websites_group = page.get_by_role('group', name='Websites')
        boxes = websites_group.get_by_role('checkbox')
        count = await boxes.count()
        for i in range(count):
            try:
                await boxes.nth(i).check()
            except Exception:
                try:
                    await boxes.nth(i).click()
                except Exception:
                    pass
    except Exception:
        # If the explicit group isn't found, try some common fallbacks (a generic 'Website' label)
        try:
            websites_group = page.get_by_role('group', name='Website')
            boxes = websites_group.get_by_role('checkbox')
            count = await boxes.count()
            for i in range(count):
                try:
                    await boxes.nth(i).check()
                except Exception:
                    try:
                        await boxes.nth(i).click()
                    except Exception:
                        pass
        except Exception:
            pass

    # 5) Ensure all Customer Groups are selected
    try:
        groups_group = page.get_by_role('group', name='Customer Groups')
        boxes = groups_group.get_by_role('checkbox')
        count = await boxes.count()
        for i in range(count):
            try:
                await boxes.nth(i).check()
            except Exception:
                try:
                    await boxes.nth(i).click()
                except Exception:
                    pass
    except Exception:
        # fallback
        try:
            groups_group = page.get_by_role('group', name='Customer Group')
            boxes = groups_group.get_by_role('checkbox')
            count = await boxes.count()
            for i in range(count):
                try:
                    await boxes.nth(i).check()
                except Exception:
                    try:
                        await boxes.nth(i).click()
                    except Exception:
                        pass
        except Exception:
            pass

    # 6) Set Coupon Type = No Coupon (automatic)
    await try_select_combobox(['Coupon', 'Coupon Type', 'Use Coupon'], option_labels=['No Coupon', 'No coupon', 'No Coupon (No coupon)'], option_values=['1', 'no_coupon'])

    # 7) Set the action to fixed cart discount and set discount amount = 10
    # The 'Apply' / 'Action' select often uses labels like "Fixed amount discount for whole cart" or value 'cart_fixed'
    await try_select_combobox(['Apply', 'Action', 'Simple Action'],
                               option_labels=['Fixed amount discount for whole cart', 'Fixed Amount', 'Fixed Amount for whole cart', 'Fixed amount discount'],
                               option_values=['cart_fixed', 'by_fixed', 'fixed'])

    # Discount amount field
    await try_fill_textbox(['Discount Amount', 'Discount amount', 'Discount Amount (Fixed)'], '10')

    # 8) Save the rule - clicking Save will navigate away, so make it the last action
    # Use the accessibility-role Save button
    try:
        # Some Magento installs place the Save button inside a form group (e.g., with role='toolbar' or within a header region).
        # Try a direct Save button first.
        await page.get_by_role('button', name='Save').click()
    except Exception:
        # try capitalized/other variants
        try:
            await page.get_by_role('button', name='Save Rule').click()
        except Exception:
            try:
                await page.get_by_role('button', name='Save and Continue Edit').click()
            except Exception:
                # As a last resort, try any button that contains 'Save' in its accessible name
                try:
                    # Using a simple text match via get_by_role; this will pick a button whose name includes 'Save'
                    await page.get_by_role('button', name=lambda n: n and 'save' in n.lower()).nth(0).click()
                except Exception:
                    # If we can't find a Save button, leave the form filled for manual save
                    pass

    # Short wait for save to process / navigation
    await asyncio.sleep(1)

